import {remindSave, remindUpdate} from "@/api/page/index";

export default {
  props: ['isShow', 'arrtId', 'type', 'formDetial'],
  data() {
    return {
      saveLoading: false,
      typeList: null,
      rules: {
        title: [{required: true, message: '标题不能为空', trigger: 'blur'}],
        remind: [{required: true, message: '内容不能为空', trigger: 'blur'}],

      },
    }
  },
  computed: {},
  mounted() {
    if (!this.formDetial) {
      this.formDetial = {};
    }
    this.initTypes();
  },
  methods: {
    initTypes() {
      this.typeList = [];
      this.typeList.push({
        name: '市',
        id: '2'
      })
      this.typeList.push({
        name: '县',
        id: '3'
      })
    },
    selectionChange(val) {
      this.selectionList = val;
    },
    submit() {
      this.$refs.submitForm.validate((valid) => {
        if (valid) {
          if (this.type == 'add') {
            this.saveLoading = true;
            remindSave(this.formDetial).then(res => {
              this.saveLoading = false
              this.$message.success('添加成功');
              this.$emit("close");
              this.$emit("refreshData");
            });
          } else if (this.type == 'edit') {
            this.saveLoading = true;
            remindUpdate(this.formDetial).then(res => {
              this.saveLoading = false
              this.$message.success('修改成功');
              this.$emit("close");
              this.$emit("refreshData");
            });
          }
        }
      })
    },
    getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    },
  }
}
